import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { config as loadEnv } from "dotenv";

export interface SampleConfig {
  appId: string;
  appSecret: string;
}

const envPath = findEnvPath(process.cwd());

function findEnvPath(startDirectory: string): string {
  let directory = startDirectory;
  while (true) {
    const candidate = join(directory, ".env");
    if (existsSync(candidate)) return candidate;

    const parent = dirname(directory);
    if (parent === directory) return join(startDirectory, ".env");
    directory = parent;
  }
}

export function loadSampleConfig(): SampleConfig {
  loadEnv({ path: envPath, quiet: true });

  const appId = process.env.TUITUI_BOT_APPID?.trim();
  const appSecret = process.env.TUITUI_BOT_SECRET?.trim();

  if (!appId || !appSecret) {
    throw new Error(
      `请设置 TUITUI_BOT_APPID 和 TUITUI_BOT_SECRET，或在 ${envPath} 中填写`,
    );
  }

  return {
    appId,
    appSecret,
  };
}
